const explicitFrom = new Set(redirects.flatMap((r) => (Array.isArray(r.from) ? r.from : [r.from])));

/** Every v3 page is also reachable at its old root URL unless a v4 page took it over. */
export function createRedirects(existingPath: string): string[] | undefined {
  const prefix = '/docs/v3/';
  if (!existingPath.startsWith(prefix)) return undefined;
  const oldRoot = '/docs/' + existingPath.slice(prefix.length);
  return explicitFrom.has(oldRoot) ? undefined : [oldRoot];
}
